// ================= ПИНЫ =================
#define TFT_CS    5
#define TFT_DC    2
#define TFT_RST   4
#define PIN_SPEED 34      // педаль газа
#define PIN_FUEL  35      // уровень топлива
#define PIN_LEFT  25      // левый поворотник
#define PIN_RIGHT 26      // правый поворотник
#define PIN_START 27      // кнопка старта мотора

Adafruit_ILI9341 tft(TFT_CS, TFT_DC, TFT_RST);

// ================= ЦВЕТА RGB565 =================
#define C_BLACK  0x0000
#define C_BG     0x0000   // фон панели: чёрный
#define C_FACE   0x0000   // циферблат: чёрный
#define C_WHITE  0xFFFF   // цифры и деления
#define C_GREY   0x7BEF   // мелкие риски
#define C_DARK   0x2104   // выключенные индикаторы
#define C_RED    0xF800   // красные зоны и стрелки
#define C_GREEN  0x07E0   // поворотники и нейтраль

// ================= НАСТРОЙКИ =================
#define IDLE_RPM   900    // обороты холостого хода
#define CRANK_MS   1500   // сколько стартер крутит мотор, мс
#define DOWN_HYST  8      // гистерезис понижения передачи, км/ч

// Заставка (эмблема Volvo)
#define FADE_IN_MS   2500
#define HOLD_MS      1000
#define FADE_OUT_MS  2500

// Вылет приборов
#define CENTER_X     160
#define CENTER_Y     122
#define FLY_FRAMES   30
#define FLY_DELAY    25

// Границы передач (макс скорость 220 км/ч)
const int   VLOW[6]    = {  0,  40,  70, 110, 150, 190};
const int   VHIGH[6]   = { 40,  70, 110, 150, 190, 220};
const float RPM_IN[6]  = {900, 2500, 2500, 2500, 2500, 2500};
const float RPM_OUT[6] = {4500, 4800, 4800, 4800, 4800, 5200};

enum Kind     { K_SPEED, K_RPM, K_TEMP, K_FUEL, K_CLOCK };
enum EngState { ENG_OFF, ENG_CRANK, ENG_RUN };

// =================================================
