// Спидометр опущен на единую ось (Y=128), чтобы надпись km/h лежала на одной линии с нижним срезом
Gauge gFuel  = {  22, 145,  15,   0, 100,  100,   0, 0.03, 0.88, K_FUEL,  nullptr, -999, -1 };
Gauge gClock = {  80, 128,  32,   0,  60,    0,   0, 0.10, 0.90, K_CLOCK, nullptr, -999, -1 };
Gauge gSpeed = { 160, 128,  42,   0, 220,    0,   0, 0.08, 0.80, K_SPEED, nullptr, -999, -1 };
Gauge gRpm   = { 240, 128,  32,   0,   7,    0,   0, 0.10, 0.78, K_RPM,   nullptr, -999, -1 };
Gauge gTemp  = { 298, 145,  15,  50, 130,   50,   0, 0.02, 0.90, K_TEMP,  nullptr, -999, -1 };

