// =================================================
//                          ФИЗИКА
// =================================================
void physStep(Gauge &g, float target) {
  target = constrain(target, g.minV, g.maxV);
  float acc = (target - g.pos) * g.stiff;
  g.vel = (g.vel + acc) * g.damp;
  g.pos += g.vel;
  if (g.pos < g.minV) { g.pos = g.minV; g.vel *= -0.3f; }
  if (g.pos > g.maxV) { g.pos = g.maxV; g.vel *= -0.3f; }
}

float degFor(const Gauge &g, float v) {
  v = constrain(v, g.minV, g.maxV);
  return 135.0f + (v - g.minV) / (g.maxV - g.minV) * 270.0f;
}

void polar(int cx, int cy, float r, float deg, int16_t &x, int16_t &y) {
  float a = deg * DEG_TO_RAD;
  x = cx + cos(a) * r;
  y = cy + sin(a) * r;
}

void arcBand(Adafruit_GFX &c, int cx, int cy, const Gauge &g,
             float v0, float v1, float rO, float rI, uint16_t col) {
  float a   = degFor(g, v0);
  float end = degFor(g, v1);
  while (a < end) {
    float b = min(a + 1.5f, end);
    int16_t x1, y1, x2, y2, x3, y3, x4, y4;
    polar(cx, cy, rO, a, x1, y1);
    polar(cx, cy, rO, b, x2, y2);
    polar(cx, cy, rI, b, x3, y3);
    polar(cx, cy, rI, a, x4, y4);
    c.fillTriangle(x1, y1, x2, y2, x3, y3, col);
    c.fillTriangle(x1, y1, x3, y3, x4, y4, col);
    a = b;
  }
}

// =================================================
//                            ТЕКСТ
// =================================================
void textAt(Adafruit_GFX &c, int x, int y, const char *s, uint16_t col, bool center = false) {
  c.setFont();
  c.setTextSize(1);
  c.setTextColor(col);
  int w = strlen(s) * 6;
  c.setCursor(center ? x - w / 2 : x, center ? y - 4 : y);
  c.print(s);
}

// Отрисовка текста ультра-компактным шрифтом (для спидометра и одометра)
void tinyTextAt(Adafruit_GFX &c, int cx, int cy, const char *s, uint16_t col) {
  c.setFont(&TomThumb);
  c.setTextSize(1);
  c.setTextColor(col);
  int16_t bx, by; uint16_t bw, bh;
  c.getTextBounds(s, 0, 0, &bx, &by, &bw, &bh);
  c.setCursor(cx - bw / 2 - bx, cy - bh / 2 - by);
  c.print(s);
  c.setFont(); // Сброс на стандартный
}

void bigText(Adafruit_GFX &c, int cx, int cy, const char *s, const GFXfont *f, uint16_t col) {
  c.setFont(f);
  c.setTextColor(col);
  int16_t bx, by;
  uint16_t bw, bh;
  c.getTextBounds(s, 0, 0, &bx, &by, &bw, &bh);
  c.setCursor(cx - bw / 2 - bx, cy - bh / 2 - by);
  c.print(s);
  c.setFont();
}

