void drawScale(Adafruit_GFX &c, int cx, int cy, const Gauge &g,
               float minorStep, float majorStep, float labelStep,
               int rOuter, int rLabel) {
  for (float v = g.minV; v <= g.maxV + 0.001f; v += minorStep) {
    bool major = fabs(fmod(v, majorStep)) < 0.001f;
    int len = major ? 5 : 2;
    int16_t x1, y1, x2, y2;
    polar(cx, cy, rOuter,       degFor(g, v), x1, y1);
    polar(cx, cy, rOuter - len, degFor(g, v), x2, y2);
    c.drawLine(x1, y1, x2, y2, major ? C_WHITE : C_GREY);
  }
  for (float v = g.minV; v <= g.maxV + 0.001f; v += labelStep) {
    char b[5];
    itoa((int)(v + 0.5f), b, 10);
    int16_t x, y;
    polar(cx, cy, rLabel, degFor(g, v), x, y);

    // Цифры спидометра делаем микро-шрифтом, остальные стандартным
    if (g.kind == K_SPEED) {
      tinyTextAt(c, x, y, b, C_WHITE);
    } else {
      textAt(c, x, y, b, C_WHITE, true);
    }
  }
}

void renderFace(Gauge &g) {
  int S = 2 * g.r + 8;
  int c = g.r + 4;

  g.face = new GFXcanvas16(S, S);
  if (!g.face || !g.face->getBuffer()) {
    tft.fillScreen(C_RED);
    Serial.println("ОШИБКА: памяти не хватает");
    while (1) delay(100);
  }

  g.face->fillScreen(C_BG);
  g.face->fillCircle(c, c, g.r + 2, C_FACE);

  if (g.kind == K_CLOCK) {
    for (int i=0; i<12; i++) {
      float a = (i * 30 - 90) * DEG_TO_RAD;
      int16_t x1 = c + cos(a) * (g.r - 2);
      int16_t y1 = c + sin(a) * (g.r - 2);
      int16_t x2 = c + cos(a) * (g.r - 6);
      int16_t y2 = c + sin(a) * (g.r - 6);
      g.face->drawLine(x1, y1, x2, y2, C_WHITE);
    }
    textAt(*g.face, c, c - g.r + 12, "12", C_WHITE, true);
    textAt(*g.face, c + g.r - 10, c, "3", C_WHITE, true);
    textAt(*g.face, c, c + g.r - 10, "6", C_WHITE, true);
    textAt(*g.face, c - g.r + 10, c, "9", C_WHITE, true);

  } else {
    if (g.kind == K_SPEED || g.kind == K_RPM) {
      if (g.kind == K_SPEED) {
        drawScale(*g.face, c, c, g, 10, 20, 20, g.r - 2, g.r - 12);
        tinyTextAt(*g.face, c, c + g.r - 12, "km/h", C_WHITE);
      } else {
        arcBand(*g.face, c, c, g, 6, 7, g.r - 2, g.r - 4, C_RED);
        drawScale(*g.face, c, c, g, 0.25f, 1, 1, g.r - 2, g.r - 12);

        // Маленькая надпись тахометра в одну строчку (опущена на единый уровень с km/h)
        tinyTextAt(*g.face, c, c + g.r - 2, "x1000 r/min", C_WHITE);
      }
    } else {
      int rOuter = g.r;
      int rInner = g.r - 2;

      if (g.kind == K_TEMP) {
        arcBand(*g.face, c, c, g, 50, 110, rOuter, rInner, C_WHITE);
        arcBand(*g.face, c, c, g, 110, 130, rOuter, rInner, C_RED);

        // Иконка температуры (вместо букв)
        int ix = c - 9; int iy = c + 1;
        g.face->drawCircle(ix+2, iy+5, 1, C_WHITE);
        g.face->drawLine(ix+1, iy, ix+1, iy+4, C_WHITE);
        g.face->drawLine(ix+3, iy, ix+3, iy+4, C_WHITE);
        g.face->drawPixel(ix+2, iy, C_WHITE);
        g.face->drawLine(ix+4, iy+1, ix+5, iy+1, C_WHITE);
        g.face->drawLine(ix+4, iy+3, ix+5, iy+3, C_WHITE);

      } else {
        arcBand(*g.face, c, c, g, 15, 100, rOuter, rInner, C_WHITE);
        arcBand(*g.face, c, c, g, 0, 15, rOuter, rInner, C_RED);

        // Иконка колонки (вместо букв)
        int ix = c - 9; int iy = c + 1;
        g.face->drawRect(ix, iy, 5, 7, C_WHITE);
        g.face->fillRect(ix+1, iy+1, 3, 2, C_WHITE);
        g.face->drawLine(ix+4, iy+2, ix+6, iy+2, C_WHITE);
        g.face->drawLine(ix+6, iy+2, ix+6, iy+5, C_WHITE);
        g.face->drawPixel(ix+5, iy+5, C_WHITE);
      }
    }
  }
}

void drawFaceAt(const Gauge &g, int x, int y) {
  int S = 2 * g.r + 8;
  int left = constrain(x - g.r - 4, 0, 320 - S);
  int top  = constrain(y - g.r - 4, 0, 240 - S);
  tft.drawRGBBitmap(left, top, g.face->getBuffer(), S, S);
}

void drawFaceFull(const Gauge &g) {
  drawFaceAt(g, g.cx, g.cy);
}

void drawNeedle(const Gauge &g, float deg, int r0, int r1, uint16_t color = C_RED) {
  float a  = deg * DEG_TO_RAD;
  float ca = cos(a), sa = sin(a);
  float px = -sa * 2.0f, py = ca * 2.0f;
  int bx = g.cx + ca * r0, by = g.cy + sa * r0;
  int tx = g.cx + ca * r1, ty = g.cy + sa * r1;
  tft.fillTriangle(tx, ty, bx + px, by + py, bx - px, by - py, color);
}

void updateGauge(Gauge &g, int state) {
  // Специальная отрисовка часов
  if (g.kind == K_CLOCK) {
    if (state == g.oldState) return;
    drawFaceFull(g);

    float hA = clockHour * 30 + clockMin * 0.5f - 90;
    float mA = clockMin * 6 + clockSec * 0.1f - 90;
    float sA = clockSec * 6 - 90;

    drawNeedle(g, hA, -4, g.r - 16, C_WHITE);
    drawNeedle(g, mA, -4, g.r - 6, C_WHITE);

    float rad = sA * DEG_TO_RAD;
    tft.drawLine(g.cx, g.cy, g.cx + cos(rad)*(g.r-4), g.cy + sin(rad)*(g.r-4), C_RED);

    tft.fillCircle(g.cx, g.cy, 4, C_BG);
    tft.drawCircle(g.cx, g.cy, 4, C_GREY);

    g.oldState = state;
    return;
  }

  float deg = degFor(g, g.pos);

  // Для спидометра дополнительно проверяем изменение ОДОМЕТРА и TRIP
  if (g.kind == K_SPEED) {
    long currentOdo = (long)(odometer * 10.0f);
    long currentTrip = (long)(trip * 10.0f);

    if (fabs(deg - g.oldDeg) < 0.3f && state == g.oldState && currentOdo == oldOdo && currentTrip == oldTrip) return;
    oldOdo = currentOdo;
    oldTrip = currentTrip;

    drawFaceFull(g);

    // Отрисовка ODO над стрелкой (компактный размер, максимально близко к центру)
    char bOdo[16];
    sprintf(bOdo, "ODO %ld.%ld", currentOdo / 10, currentOdo % 10);
    tft.fillRect(g.cx - 21, g.cy - 18, 42, 8, C_DARK);
    tinyTextAt(tft, g.cx, g.cy - 14, bOdo, C_WHITE);

    // Отрисовка TRIP под стрелкой (компактный размер, максимально близко к центру)
    char bTrip[16];
    sprintf(bTrip, "TRIP %ld.%ld", currentTrip / 10, currentTrip % 10);
    tft.fillRect(g.cx - 21, g.cy + 10, 42, 8, C_DARK);
    tinyTextAt(tft, g.cx, g.cy + 14, bTrip, C_WHITE);

  } else {
    if (fabs(deg - g.oldDeg) < 0.3f && state == g.oldState) return;
    drawFaceFull(g);
  }

  // Отрисовка красной стрелки
  if (g.kind == K_SPEED || g.kind == K_RPM) {
    drawNeedle(g, deg, -4, g.r - 6, C_RED); 
  } else {
    drawNeedle(g, deg, -4, g.r - 4, C_RED); 
  }

  // Черная "заглушка" основания стрелки
  tft.fillCircle(g.cx, g.cy, 4, C_BG);
  tft.drawCircle(g.cx, g.cy, 4, C_GREY);

  g.oldDeg   = deg;
  g.oldState = state;
}

