void updateGear() {
  if (speedKmh < 2) { curGear = 1; return; }
  int before = curGear;
  while (curGear < 6 && speedKmh >= VHIGH[curGear - 1]) curGear++;
  while (curGear > 1 && speedKmh < VLOW[curGear - 1] - DOWN_HYST) curGear--;
}

float calcRpm() {
  if (engState == ENG_OFF)   return 0;
  if (engState == ENG_CRANK) return IDLE_RPM;
  if (speedKmh < 2)          return IDLE_RPM;
  int g = curGear - 1;
  float r = RPM_IN[g] + (speedKmh - VLOW[g]) * (RPM_OUT[g] - RPM_IN[g])
                        / (VHIGH[g] - VLOW[g]);
  return constrain(r, IDLE_RPM, 7000.0f);
}

void drawGearIndicator() {
  static int oldG = -1;
  int currentG = (engState == ENG_RUN && speedKmh >= 2) ? curGear : 0;
  if (currentG == oldG) return;

  tft.fillRect(145, 10, 30, 20, C_BG); 

  char bg[4];
  uint16_t col = C_WHITE;

  if (currentG == 0) {
    strcpy(bg, "N");
    col = C_GREEN;
  } else {
    sprintf(bg, "%d", currentG);
  }

  tft.setTextSize(2);
  tft.setTextColor(col);

  int16_t bx, by; uint16_t bw, bh;
  tft.getTextBounds(bg, 0, 0, &bx, &by, &bw, &bh);
  tft.setCursor(160 - bw / 2, 12); 
  tft.print(bg);
  tft.setTextSize(1);

  oldG = currentG;
}

void drawShiftLight() {
  static int oldState = -1;
  bool up = (engState == ENG_RUN) && gear > 0 && gear < 6
            && gRpm.pos >= 4.5f && blinkPhase;
  int st = up ? 1 : 0;
  if (st == oldState) return;
  oldState = st;

  tft.fillRect(224, 44, 32, 18, C_BG);
  if (up) tft.fillTriangle(240, 46, 231, 60, 249, 60, C_GREEN);
}

