void drawArrows() {
  bool l = leftOn  && blinkPhase;
  bool r = rightOn && blinkPhase;
  if (l == oldL && r == oldR) return;
  oldL = l; oldR = r;

  tft.fillRect(90, 4, 40, 28, C_BG);
  tft.fillRect(190, 4, 40, 28, C_BG);

  uint16_t cl = l ? C_GREEN : C_DARK;
  uint16_t cr = r ? C_GREEN : C_DARK;

  tft.fillTriangle(106, 18, 122, 8, 122, 28, cl);
  tft.fillRect(122, 14, 14, 8, cl);

  tft.fillRect(184, 14, 14, 8, cr);
  tft.fillTriangle(214, 18, 198, 8, 198, 28, cr);
