uint16_t greyRGB(int v) {
  if (v < 0)   v = 0;
  if (v > 255) v = 255;
  return ((v >> 3) << 11) | ((v >> 2) << 5) | (v >> 3);
}

void drawVolvoLogo(int cx, int cy, float k) {
  const int RO = 80;
  const int RI = 64;
  for (int y = cy - RO; y <= cy + RO; y++) {
    int dy = y - cy;
    int wo = (int)sqrt((float)(RO * RO - dy * dy));
    int wi = (abs(dy) < RI) ? (int)sqrt((float)(RI * RI - dy * dy)) : 0;
    float t = (y - (cy - RO)) / (float)(2 * RO);
    uint16_t col = greyRGB((int)((235.0f - 150.0f * t) * k));
    int w = wo - wi;
    if (w > 0) {
      tft.drawFastHLine(cx - wo, y, w, col);
      tft.drawFastHLine(cx + wi, y, w, col);
    }
  }

  const float ux = 0.7071f, uy = -0.7071f;
  const float px = -uy, py = ux;
  uint16_t arrowCol = greyRGB((int)(240 * k));
  float tailR = RO - 14, headR = RO + 14, tipR  = RO + 34;

  int tAx = cx + ux * tailR + px * 6, tAy = cy + uy * tailR + py * 6;
  int tBx = cx + ux * tailR - px * 6, tBy = cy + uy * tailR - py * 6;
  int hAx = cx + ux * headR + px * 6, hAy = cy + uy * headR + py * 6;
  int hBx = cx + ux * headR - px * 6, hBy = cy + uy * headR - py * 6;

  tft.fillTriangle(tAx, tAy, tBx, tBy, hAx, hAy, arrowCol);
  tft.fillTriangle(tBx, tBy, hBx, hBy, hAx, hAy, arrowCol);

  int tipX = cx + ux * tipR, tipY = cy + uy * tipR;
  int bAx = cx + ux * headR + px * 14, bAy = cy + uy * headR + py * 14;
  int bBx = cx + ux * headR - px * 14, bBy = cy + uy * headR - py * 14;
  tft.fillTriangle(tipX, tipY, bAx, bAy, bBx, bBy, arrowCol);

  uint16_t barCol = greyRGB((int)(225 * k));
  tft.fillRect(cx - RI + 4, cy - 14, 2 * RI - 8, 3, barCol);
  tft.fillRect(cx - RI + 4, cy + 11, 2 * RI - 8, 3, barCol);
  bigText(tft, cx, cy, "VOLVO", &FreeSansBold18pt7b, greyRGB((int)(240 * k)));
}

// =================================================
//                  ЗАСТАВКА И ВЫЛЕТ ПРИБОРОВ
// =================================================
void fadeLogo(bool fadeIn, unsigned long duration) {
  unsigned long start = millis();
  while (true) {
    unsigned long el = millis() - start;
    if (el >= duration) break;
    float t = (float)el / (float)duration;
    float k = fadeIn ? t : 1.0f - t;
    tft.fillScreen(C_BLACK);
    drawVolvoLogo(160, 120, k);
  }
  tft.fillScreen(C_BLACK);
  if (fadeIn) drawVolvoLogo(160, 120, 1.0f);
}

void splash() {
  fadeLogo(true,  FADE_IN_MS);
  delay(HOLD_MS);
  fadeLogo(false, FADE_OUT_MS);
  tft.fillScreen(C_BLACK);
  delay(200);
}

float easeOutBack(float t) {
  const float c1 = 1.2f, c3 = c1 + 1.0f;
  float u = t - 1.0f;
  return 1.0f + c3 * u * u * u + c1 * u * u;
}

void flyOut() {
  Gauge *gs[5] = { &gFuel, &gClock, &gSpeed, &gRpm, &gTemp };
  for (int f = 0; f <= FLY_FRAMES; f++) {
    float t = (float)f / FLY_FRAMES;
    float e = easeOutBack(t);
    tft.fillScreen(C_BG);
    for (int i = 0; i < 5; i++) {
      int x = CENTER_X + (gs[i]->cx - CENTER_X) * e;
      int y = CENTER_Y + (gs[i]->cy - CENTER_Y) * e;
      drawFaceAt(*gs[i], x, y);
    }
    delay(FLY_DELAY);
  }
  tft.fillScreen(C_BG);
}

// =================================================
//                         SETUP
// =================================================
void setup() {
  Serial.begin(115200);
  pinMode(PIN_LEFT,  INPUT_PULLUP);
  pinMode(PIN_RIGHT, INPUT_PULLUP);
  pinMode(PIN_START, INPUT_PULLUP);

  tft.begin();
  tft.setRotation(1);

  splash();

  renderFace(gFuel);
  renderFace(gClock);
  renderFace(gSpeed);
  renderFace(gRpm);
  renderFace(gTemp);

  flyOut();

  drawFaceFull(gFuel);
  drawFaceFull(gClock);
  drawFaceFull(gSpeed);
  drawFaceFull(gRpm);
  drawFaceFull(gTemp);

  oldL = true; oldR = true;
  oldOdo = -1;
  oldTrip = -1;

  gSpeed.vel = 12;
  gRpm.vel   = 0.3f;

  lastOdo = millis();
  clockTimer = millis(); 
}

// =================================================
//                           LOOP
// =================================================
void loop() {
  unsigned long now = millis();

  // --- Ход часов ---
  if (now - clockTimer >= 1000) {
    clockSec++;
    if (clockSec >= 60) { clockSec = 0; clockMin++; }
    if (clockMin >= 60) { clockMin = 0; clockHour++; }
    if (clockHour >= 12) { clockHour = 0; }
    clockTimer = now;
  }

  // --- Кнопка «Старт / Стоп» ---
  bool startDown = (digitalRead(PIN_START) == LOW);
  if (startDown && !startWasDown && now - lastStartBtn > 300) {
    lastStartBtn = now;
    if (engState == ENG_OFF) {
      engState   = ENG_CRANK;
      crankStart = now;
    } else {
      engState = ENG_OFF;
    }
  }
  startWasDown = startDown;

  if (engState == ENG_CRANK && now - crankStart >= CRANK_MS) {
    engState = ENG_RUN;
  }

  // --- Датчики ---
  int throttle = map(analogRead(PIN_SPEED), 0, 4095, 0, 220);
  fuelPct = map(analogRead(PIN_FUEL), 0, 4095, 0, 100);
  speedKmh = (engState == ENG_RUN) ? throttle : 0;

  // --- Передачи и обороты ---
  updateGear();
  gear = (engState == ENG_RUN && speedKmh >= 2) ? curGear : 0;
  rpm  = calcRpm();

  // --- Нагрев двигателя ---
  if (now - lastSim > 200) {
    float target = (engState == ENG_OFF) ? 50.0f
                 : 75.0f + (rpm / 7000.0f) * 45.0f;
    engTemp += (target - engTemp) * 0.03f;
    lastSim = now;
  }

  // --- Кнопки поворотников ---
  if (digitalRead(PIN_LEFT) == LOW && now - lastBtnL > 300) {
    leftOn = !leftOn; if (leftOn) rightOn = false; lastBtnL = now;
  }
  if (digitalRead(PIN_RIGHT) == LOW && now - lastBtnR > 300) {
    rightOn = !rightOn; if (rightOn) leftOn = false; lastBtnR = now;
  }

  // --- Мигание ---
  if (now - lastBlink > 400) {
    blinkPhase = !blinkPhase;
    lastBlink = now;
  }

  // --- Одометр и суточный пробег (TRIP) ---
  if (now - lastOdo >= 100) {
    float dtMs = (float)(now - lastOdo);
    odometer += (float)speedKmh * dtMs / 3600000.0f;
    trip     += (float)speedKmh * dtMs / 3600000.0f;
    lastOdo = now;
  }

  // --- Физика стрелок ---
  if (now - lastPhys >= 20) {
    physStep(gSpeed, speedKmh);
    physStep(gRpm,   rpm / 1000.0f);
    physStep(gTemp,  engTemp);
    physStep(gFuel,  fuelPct);
    lastPhys = now;
  }

  // --- Вывод ---
  if (now - lastRender >= 40) {
    updateGauge(gFuel,  fuelPct < 15 ? (blinkPhase ? 2 : 1) : 0);
    updateGauge(gClock, clockSec);
    updateGauge(gSpeed, (int)gSpeed.pos);
    updateGauge(gRpm,   gear);
    updateGauge(gTemp,  0);

    drawArrows();
    drawGearIndicator();
    drawRpmLamp();
    drawShiftLight();

    lastRender = now;
  }
}
